{
  "name": "USBTMC通信组件",
  "name_en": "USBTMC Communicator",
  "manufacturer": "",
  "description": "用于实验系统与支持 USBTMC 的测试测量仪器之间进行读写通信的非实体通信组件。它封装了基于 USBTMC 的连接，提供地址、终止符、超时等属性管理，以及文本和原始字节的读取、写入与连接关闭等文件式 I/O 操作。",
  "description_en": "A non-physical communication component used to read from and write to USBTMC-compatible test and measurement instruments in laboratory systems. It wraps a USBTMC connection and provides property management for address, terminator, and timeout, along with file-like I/O operations such as text/raw byte read, write, and connection close.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "关闭USBTMC通信连接。",
      "description_en": "Close the USBTMC communication connection."
    },
    {
      "action_name": "auto-flush_input",
      "description": "刷新输入缓冲区（对USBTMC连接通常不执行实际操作）。",
      "description_en": "Flush the input buffer (typically a no-op for a USBTMC connection)."
    },
    {
      "action_name": "auto-read",
      "description": "从USBTMC连接读取并解码文本。",
      "description_en": "Read and decode text from the USBTMC connection."
    },
    {
      "action_name": "auto-read_raw",
      "description": "从USBTMC连接读取原始字节。",
      "description_en": "Read raw bytes from the USBTMC connection."
    },
    {
      "action_name": "auto-seek",
      "description": "设置通信流中的当前位置偏移。",
      "description_en": "Set the current position offset in the communication stream."
    },
    {
      "action_name": "auto-tell",
      "description": "获取通信流中的当前位置。",
      "description_en": "Get the current position in the communication stream."
    },
    {
      "action_name": "auto-terminator",
      "description": "获取/设置通信终止字符。",
      "description_en": "Get/set the communication termination character."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取/设置通信超时。",
      "description_en": "Get/set the communication timeout."
    },
    {
      "action_name": "auto-write",
      "description": "向USBTMC连接写入文本。",
      "description_en": "Write text to the USBTMC connection."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向USBTMC连接写入原始字节。",
      "description_en": "Write raw bytes to the USBTMC connection."
    },
    {
      "action_name": "auto-address",
      "description": "获取USBTMC地址。",
      "description_en": "Get the USBTMC address."
    }
  ],
  "tag_hints": [
    "USBTMC communication",
    "USB test and measurement",
    "SCPI over USB",
    "instrument I/O",
    "text and binary read/write",
    "timeout handling",
    "terminator configuration"
  ]
}

